    toc_list = []
    for item in toc:
        if item.level == min_level:
            toc_list.append(item)
        elif item.level > min_level:
            toc_list.extend(toc_to_list(item.children, min_level, max_level))
        if item.level == max_level:
            break
    return toc_list

