def toc_to_state(toc_list, min_level=1, max_level=3, heading_id=None):
    toc_text = ''
    for item in toc_list:
        if item.level < min_level or item.level > max_level:
            continue
        if heading_id:
            item.link = heading_id(item.text)
        else:
            item.link = item.text.replace(' ', '-')
        toc_text += '<li><a href="#%s">%s</a></li>\n' % (item.link, item.text)
    return toc_text

