def toc_treeprocessor(md, toc_tokens):
    """ Build a TOC TreeProcessor """
    toc_tree = []
    for i in toc_tokens:
        if i['level'] < min_level or i['level'] > max_level:
            continue
        toc_item = {
            'level': i['level'],
            'id': heading_id(i['text']),
            'name': i['text']
        }
        toc_tree.append(toc_item)
    md.env['toc_tree'] = toc_tree

