sql = sqlparse.format(sql, strip_comments=True)
# Split into tokens
tokens = sqlparse.parse(sql)[0].tokens
# Find last keyword
for token in tokens[::-1]:
    if token.ttype in (Token.Keyword, Token.Keyword.DDL, Token.Keyword.DML):
        break
if isinstance(token, Identifier):
    keyword = token.get_name()
else:
    keyword = token.value
# Find start of query
for start_i in range(len(tokens) - 1, 0, -1):
    if tokens[start_i].ttype in (Token.Keyword, Token.Keyword.DDL, Token.Keyword.DML):
        break
start_i += 1
# Return results
return (keyword, sqlparse.format(sql[0:tokens[start_i].pos_to_lineno()[1]].strip(), strip_comments=True))

