# Split the SQL statement into tokens.
tokens = sqlparse.parse(sql)[0].flatten()
# Get the last n tokens.
last_n_tokens = tokens[-(n_skip + 1):]
# Get the last token.
last_token = last_n_tokens[-1]
# If the last token is a keyword, return the value of the last token.
if last_token.ttype in (Token.Keyword, Token.Keyword.DDL, Token.Keyword.Reserved):
    return (last_token.value, sql[:sql.find(last_token.value)])
# If the second to last token is a keyword, return the value of the second to last token.
elif last_n_tokens[-2].ttype in (Token.Keyword, Token.Keyword.DDL, Token.Keyword.Reserved):
    return (last_n_tokens[-2].value, sql[:sql.find(last_n_tokens[-2].value)])
# Otherwise, return None.
else:
    return (None, sql)

# Remove spaces, comments, and line breaks, and lowercase the string
sql = re.sub(r'--.*$', '', sql.strip(), flags=re.MULTILINE).lower()

# Split the string into tokens
tokens = sql.split()

# If there are no tokens, return an empty string
if len(tokens) == 0:
    return '', ''

# Find the index of the last keyword
last_keyword_idx = 0
for i in reversed(range(len(tokens))):
    if tokens[i] in KEYWORDS:
        last_keyword_idx = i
        break

# If the last keyword is the first token, then there is nothing to strip
if last_keyword_idx == 0:
    return tokens[0], sql

# If there are more than n_skip tokens after the last keyword, strip them
if len(tokens) - last_keyword_idx > n_skip + 1:
    return tokens[0], ' '.join(tokens[:last_keyword_idx + 1])

# If there are less than or equal to n_skip tokens after the last keyword, strip all of them
return tokens[0], ' '.join(tokens[:last_keyword_idx])

