# Convert the input bytes to the largest possible unit ("bytes", "KB", "MB", "GB", and "TB")
bytes = float(bytes)
KB = float(1024)
MB = float(KB ** 2)  # 1,048,576
GB = float(KB ** 3)  # 1,073,741,824
TB = float(KB ** 4)  # 1,099,511,627,776

def format_bytes_unit(x, suffixes=None):
    if suffixes is None:
        suffixes = ["bytes", "KB", "MB", "GB", "TB"]

    if x < KB:
        return f"{x:.2f}{suffixes[0]}"
    elif KB <= x < MB:
