class ReadTransaction:

    def __init__(self, file_memory):
        self._file_memory = file_memory

    def __enter__(self):
        self._file_memory._lock.reader_acquire()

    def __exit__(self, type, value, traceback):
        self._file_memory._lock.reader_release()

return ReadTransaction(self)

class ReadTransaction:

    def __init__(self, file_memory):
        self.file_memory = file_memory

    def __enter__(self):
        self.file_memory._lock.reader_acquire()
        return self

    def __exit__(self, *args):
        self.file_memory._lock.reader_release()

return ReadTransaction(self)

