    return k.replace('_', '-').replace('.', '-')

def _format_value(v):
    return str(v).replace(',', '\,').replace('=', '\=')

def _format_kv(k, v):
    return '{}={}'.format(_format_key(k), _format_value(v))

def _format_entry(k, v):
    return '{} {}'.format(_format_key(k), _format_value(v))

def _format_kv_pairs(d):
    return ' '.join([_format_kv(k, v) for k, v in d.items()])

