# Create a dictionary of models to their children.
model_children = {}
for model in models:
    model_children[model] = [field.rel_model for field in model._meta.fields
                             if field.rel_model is not None]

# Create a list of models with no children.
models_without_children = []

# Use a depth-first search to recursively find models without children.
for model in models:
    if not model_children.get(model):
        models_without_children.append(model)

# Create a list to hold the sorted models.
sorted_models = []

# Iterate over models without children and add them to the sorted models list.
while models_without_children:
    model = models_without_children.pop()
    sorted_models.append(model)

    # Remove the current model from the children of all models.
    for model in model_children:
        if model != model and model in model_children[model]:
            model_children[model].remove(model)

    # Add all models without children to the list of models to sort.
    for model in model_children:
        if not model_children[model]:
            models_without_children.append(model)

return sorted_models

