    # If a permission is not prefixed with + or -, it is added.
    permissions_to_add = [
        permission[1:] for permission in permissions if permission.startswith("+")
    ]
    permissions_to_remove = [
        permission[1:] for permission in permissions if permission.startswith("-")
    ]
    permissions_to_add.extend(
        [
            permission
            for permission in known_permissions
            if permission not in permissions and permission not in permissions_to_add
        ]
    )
    return ",".join(permissions_to_add) + "," + ",".join(permissions_to_remove)

