def render_children(children, indent, pretty, xhtml):
  """
  Recursively renders the children of the DOM tag.
  Input-Output Arguments
  :param children: List. The children of the DOM tag.
  :param indent: String. The string used for indentation.
  :param pretty: Bool. Whether to add line breaks and indentation for a prettier output.
  :param xhtml: Bool. Whether to use XHTML syntax.
  :return: String. The rendered output of the children of the DOM tag.
  """
  if pretty:
    # Add line breaks and indentation for a prettier output
    return indent + indent.join(
        render_child(child, indent, pretty, xhtml)
        for child in children)
  else:
    # Do not add line breaks or indentation for a more compact output
    return ''.join(
        render_child(child, indent, pretty, xhtml)
