for p in parsed:
    tbl_prefix_seen = False
    for item in p.tokens:
        # If it's a keyword, it's not a table
        if item.ttype is Keyword:
            tbl_prefix_seen = False
        # If we see a dot, it's the table prefix
        elif item.value == ".":
            tbl_prefix_seen = True
        # If we see a lparen, it's the start of a subquery or function; stop
        elif item.value == "(":
            break
        # If we see a comma, it's the end of a column list in a table definition
        elif item.value == ",":
            tbl_prefix_seen = False
        # If we see a colon, it's the start of the column definitions in a table definition
        elif item.value == ":":
            break
        # If we see a semicolon, it's the end of the statement
        elif item.value == ";":
            break

        # If we see any other token, it's a table reference
        elif item.ttype not in (
            Punctuation,
            Keyword,
            Whitespace,
            Newline,
            Comment,
        ):
            # If we see a star, it's all the columns, which we ignore
            if item.value == "*":
                continue

            # If we're in the prefix, we're not seeing a table reference
            if tbl_prefix_seen:
                tbl_prefix_seen = False
            else:
                for table in extract_table_identifiers(item):
                    extracted_tables.append(table)

return extracted_tables

