def json_encode(value):
    if isinstance(value, Component):
        return value.to_plotly_json()
    if isinstance(value, dict):
        return {k: json_encode(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_encode(v) for v in value]
    if isinstance(value, (str, int, float, bool)):
        return value
    if value is None:
        return None
    if isinstance(value, Component._UNDEFINED):
        return None
    if isinstance(value, Component.REQUIRED):
        raise ValueError(
            "Cannot JSON-serialize a REQUIRED value. "
            "Did you forget to assign a value to a property?"
        )
    raise ValueError(
        f"Cannot JSON-serialize value {value!r} of type {type(value)}"
    )

