# This function is used to validate the color codes of a theme.
def validate_color_codes(color: str) -> str:
    if color in valid_16_color_codes:
        return color
    else:
        raise InvalidThemeColorCode(f"Invalid color code: {color}")

# This function is used to convert the color codes of a theme to the specified color depth.
def convert_color_codes(color: str, color_depth: int) -> str:
    if color_depth == 1:
        return ""
    elif color_depth == 16:
        return color
    elif color_depth == 256:
        return f"color{color}"
    elif color_depth == 2 ** 24:
        return f"color{color}, bold"
    else:
        raise ValueError("Invalid color depth")

# This function is used to convert the properties of a theme to the specified color depth.
def convert_properties(prop: str, color_depth: int) -> str:
    if color_depth == 1:
        return ""
    elif color_depth == 16:
        return prop
    elif color_depth == 256:
        return prop
    elif color_depth == 2 ** 24:
        if prop == "bold":
            return "bold"
        else:
            return ""
    else:
        raise ValueError("Invalid color depth")

